@startuml

class Customer {
  + name : string
  + phoneNumber : string
  + email : string
}

class CarOwner {
  + name : string
  + phoneNumber : string
  + email : string
}

abstract class TaxiService {}

class RideHailing extends TaxiService {
  + pickupTime : datetime
  + dropOffTime : datetime
  + pickupLocation : string
  + dropOffLocation : string
  + rideDuration : int
  + distance : float
  + numberOfPassengers : int
  + fee : double
  + requestType : string
  + leadCustomerName : string
}

class RideSharing extends TaxiService {
  + pickupTime : datetime
  + dropOffTime : datetime
  + pickupLocation : string
  + dropOffLocation : string
  + rideDuration : int
  + distance : float
  + customerNames : string[]
  + upfrontFee : double
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class Car {
  + carNumber : string
  + tonnage : double
  + seats : int
}

abstract class Vehicle {}

class SelfDrivingCar extends Vehicle {
  + isAvailable : boolean
}

class RegisteredCar extends Vehicle {
  + owner : CarOwner
}

Customer "1" -- "0..*" RideHailing
Customer "1" -- "0..*" RideSharing
CarOwner "1" *-- "0..*" RegisteredCar
SelfDrivingCar --|> Vehicle
RegisteredCar --|> Vehicle
RideHailing --|> TaxiService
RideSharing --|> TaxiService
Accident "*--" Car

@enduml

